=== EVENT NODE (claim 1a) ===
use anyhow::{Result, anyhow};
use rkyv::{Archive, Deserialize, Serialize, rancor::Error as RkyvError};

use crate::archive::{unwrap_archive_payload, wrap_archive_payload};
use crate::{ContentHash, NodeId};

#[derive(Archive, Serialize, Deserialize, Clone, Debug, PartialEq)]
pub struct EventNodeOwned {
    pub id: NodeId,
    pub parent_id: Option<NodeId>,
    pub path: Option<String>,
    pub timestamp: i64,
    pub timestamp_vector: Vec<f32>,
    pub content_hash: Option<ContentHash>,
    pub content_uri: Option<String>,
    pub vector_uri: Option<String>,
    pub payload: Vec<u8>,
    pub schema_type: Option<String>,
    pub entities_involved: Vec<String>,
    pub community_members: Vec<String>,
}

pub fn encode_event_node(node: &EventNodeOwned) -> Result<Vec<u8>> {
    let payload = rkyv::to_bytes::<RkyvError>(node)
        .map_err(|e| anyhow!("rkyv encode EventNodeOwned: {e}"))?;
    Ok(wrap_archive_payload(&payload))
}

pub fn decode_event_node(bytes: &[u8]) -> Result<EventNodeOwned> {
    let payload = unwrap_archive_payload(bytes)?;
