//! Code domain types and helpers for V3.
//!
//! This crate provides:
//! - Code file payload structs for AST/code ingestion
//! - Symbol payloads for function/class indexing
//! - Edge types for imports and call graphs
//!
//! NOTE: This is a scaffold only. No parser/indexing pipeline yet.
//! Schemas are stable and versioned early for future expansion.

use serde::{Deserialize, Serialize};

use cognitiveos_v3_core::NodeId;

/// Programming language enum.
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq, Hash)]
pub enum Language {
    Rust,
    Python,
    JavaScript,
    TypeScript,
    Go,
    Java,
    C,
    Cpp,
    Ruby,
    PHP,
    Swift,
    Kotlin,
    Scala,
    Other(String),
}

impl Language {
    pub fn from_extension(ext: &str) -> Self {
        match ext.to_lowercase().as_str() {
            "rs" => Language::Rust,
            "py" => Language::Python,
            "js" | "mjs" | "cjs" => Language::JavaScript,
            "ts" | "tsx" => Language::TypeScript,
            "go" => Language::Go,
            "java" => Language::Java,
            "c" => Language::C,
            "cpp" | "cc" | "cxx" => Language::Cpp,
            "rb" => Language::Ruby,
            "php" => Language::PHP,
            "swift" => Language::Swift,
            "kt" | "kts" => Language::Kotlin,
            "scala" => Language::Scala,
            other => Language::Other(other.to_string()),
        }
    }

    pub fn extension(&self) -> &str {
        match self {
            Language::Rust => "rs",
            Language::Python => "py",
            Language::JavaScript => "js",
            Language::TypeScript => "ts",
            Language::Go => "go",
            Language::Java => "java",
            Language::C => "c",
            Language::Cpp => "cpp",
            Language::Ruby => "rb",
            Language::PHP => "php",
            Language::Swift => "swift",
            Language::Kotlin => "kt",
            Language::Scala => "scala",
            Language::Other(s) => s,
        }
    }
}

/// Symbol kind for code indexing.
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq, Hash)]
pub enum SymbolKind {
    Function,
    Method,
    Class,
    Struct,
    Interface,
    Enum,
    Constant,
    Variable,
    Module,
    Namespace,
    TypeAlias,
    Trait,
    Macro,
}

/// Payload for code file nodes.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct CodeFilePayload {
    /// File path relative to repository root.
    pub path: String,
    /// Programming language.
    pub language: Language,
    /// Repository ID (if part of a known repo).
    pub repo_id: Option<String>,
    /// Git commit SHA (if versioned).
    pub commit_sha: Option<String>,
    /// File content hash.
    pub content_hash: String,
    /// Number of lines.
    pub line_count: usize,
    /// Detected imports (module names).
    pub imports: Vec<String>,
    /// Detected exports (symbol names).
    pub exports: Vec<String>,
    /// Top-level symbols (functions, classes, etc.).
    pub symbols: Vec<String>,
}

/// Payload for symbol nodes (functions, classes, etc.).
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct SymbolPayload {
    /// Symbol name.
    pub name: String,
    /// Fully qualified name (with namespace/class prefix).
    pub qualified_name: String,
    /// Symbol kind.
    pub kind: SymbolKind,
    /// Language.
    pub language: Language,
    /// Source file path.
    pub file_path: String,
    /// Start line (1-indexed).
    pub start_line: usize,
    /// End line (1-indexed).
    pub end_line: usize,
    /// Signature (for functions).
    pub signature: Option<String>,
    /// Docstring/comment.
    pub docstring: Option<String>,
    /// Parameters (for functions).
    pub parameters: Vec<ParameterInfo>,
    /// Return type.
    pub return_type: Option<String>,
}

/// Parameter information for function symbols.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct ParameterInfo {
    pub name: String,
    pub type_annotation: Option<String>,
    pub default_value: Option<String>,
}

/// Edge type for import relationships.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct ImportEdge {
    /// Source file node ID.
    pub from_file: NodeId,
    /// Imported symbol name or module path.
    pub import_name: String,
    /// Target module/package (may not have a node if external).
    pub target_module: String,
    /// Import kind (named, default, star).
    pub import_kind: ImportKind,
}

/// Import kind.
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub enum ImportKind {
    Named,
    Default,
    Star,
}

/// Edge type for call graph relationships.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct CallEdge {
    /// Caller symbol node ID.
    pub caller: NodeId,
    /// Callee symbol node ID (may be None for external calls).
    pub callee: Option<NodeId>,
    /// Callee name (for resolution).
    pub callee_name: String,
    /// Call site line number.
    pub line: usize,
}

/// Path helper for code nodes.
pub struct CodePaths;

impl CodePaths {
    /// Generate path for a code file.
    pub fn file_path(domain: &str, repo_id: Option<&str>, file_path: &str) -> String {
        match repo_id {
            Some(repo) => format!("/{}/code/{}/{}", domain, repo, file_path),
            None => format!("/{}/code/{}", domain, file_path),
        }
    }

    /// Generate path for a symbol.
    pub fn symbol_path(
        domain: &str,
        repo_id: Option<&str>,
        file_path: &str,
        symbol_name: &str,
    ) -> String {
        match repo_id {
            Some(repo) => format!("/{}/code/{}/{}#{}", domain, repo, file_path, symbol_name),
            None => format!("/{}/code/{}#{}", domain, file_path, symbol_name),
        }
    }

    /// Generate node ID for a code file.
    pub fn file_node_id(file_path: &str, content_hash: &str) -> NodeId {
        NodeId::new(format!("code/file/{}/{}", file_path, &content_hash[..8]))
            .expect("valid node id")
    }

    /// Generate node ID for a symbol.
    pub fn symbol_node_id(file_path: &str, qualified_name: &str) -> NodeId {
        NodeId::new(format!("code/symbol/{}/{}", file_path, qualified_name)).expect("valid node id")
    }
}

/// Builder for creating code nodes.
pub struct CodeNodeBuilder {
    domain: String,
}

impl CodeNodeBuilder {
    pub fn new(domain: impl Into<String>) -> Self {
        Self {
            domain: domain.into(),
        }
    }

    /// Create a code file node.
    pub fn create_file(&self, payload: CodeFilePayload) -> cognitiveos_v3_core::EventNodeOwned {
        let path = CodePaths::file_path(&self.domain, payload.repo_id.as_deref(), &payload.path);
        let node_id = CodePaths::file_node_id(&payload.path, &payload.content_hash);
        let payload_bytes =
            cognitiveos_v3_core::encode_payload_gzip_json(&payload).expect("encode payload");

        cognitiveos_v3_core::EventNodeOwned {
            id: node_id,
            parent_id: None,
            path: Some(path),
            timestamp: 0,
            timestamp_vector: vec![],
            content_hash: None,
            content_uri: None,
            vector_uri: None,
            payload: payload_bytes,
            schema_type: Some("code/file".to_string()),
            entities_involved: vec![],
            community_members: vec![],
        }
    }

    /// Create a symbol node.
    pub fn create_symbol(
        &self,
        payload: SymbolPayload,
        parent_id: NodeId,
    ) -> cognitiveos_v3_core::EventNodeOwned {
        let path = CodePaths::symbol_path(
            &self.domain,
            None,
            &payload.file_path,
            &payload.qualified_name,
        );
        let node_id = CodePaths::symbol_node_id(&payload.file_path, &payload.qualified_name);
        let payload_bytes =
            cognitiveos_v3_core::encode_payload_gzip_json(&payload).expect("encode payload");

        cognitiveos_v3_core::EventNodeOwned {
            id: node_id,
            parent_id: Some(parent_id),
            path: Some(path),
            timestamp: 0,
            timestamp_vector: vec![],
            content_hash: None,
            content_uri: None,
            vector_uri: None,
            payload: payload_bytes,
            schema_type: Some("code/symbol".to_string()),
            entities_involved: vec![],
            community_members: vec![],
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_language_from_extension() {
        assert_eq!(Language::from_extension("rs"), Language::Rust);
        assert_eq!(Language::from_extension("py"), Language::Python);
        assert_eq!(Language::from_extension("ts"), Language::TypeScript);
        assert_eq!(
            Language::from_extension("unknown"),
            Language::Other("unknown".to_string())
        );
    }

    #[test]
    fn test_code_paths() {
        let path = CodePaths::file_path("code", Some("my-repo"), "src/main.rs");
        assert!(path.contains("my-repo"));
        assert!(path.contains("src/main.rs"));

        let sym_path = CodePaths::symbol_path("code", None, "lib.rs", "MyStruct");
        assert!(sym_path.contains("lib.rs"));
        assert!(sym_path.contains("MyStruct"));
    }

    #[test]
    fn test_symbol_payload() {
        let payload = SymbolPayload {
            name: "my_function".to_string(),
            qualified_name: "mymodule::my_function".to_string(),
            kind: SymbolKind::Function,
            language: Language::Rust,
            file_path: "src/lib.rs".to_string(),
            start_line: 10,
            end_line: 20,
            signature: Some("fn my_function(x: i32) -> bool".to_string()),
            docstring: Some("Does something useful.".to_string()),
            parameters: vec![ParameterInfo {
                name: "x".to_string(),
                type_annotation: Some("i32".to_string()),
                default_value: None,
            }],
            return_type: Some("bool".to_string()),
        };

        assert_eq!(payload.name, "my_function");
        assert_eq!(payload.kind, SymbolKind::Function);
    }

    #[test]
    fn test_code_file_payload() {
        let payload = CodeFilePayload {
            path: "src/main.rs".to_string(),
            language: Language::Rust,
            repo_id: Some("my-repo".to_string()),
            commit_sha: Some("abc123".to_string()),
            content_hash: "def456".to_string(),
            line_count: 100,
            imports: vec!["std::collections::HashMap".to_string()],
            exports: vec!["main".to_string()],
            symbols: vec!["main".to_string()],
        };

        assert_eq!(payload.language, Language::Rust);
        assert_eq!(payload.line_count, 100);
    }

    #[test]
    fn test_import_edge() {
        let edge = ImportEdge {
            from_file: CodePaths::file_node_id("src/lib.rs", "abc123def456"),
            import_name: "HashMap".to_string(),
            target_module: "std::collections".to_string(),
            import_kind: ImportKind::Named,
        };

        assert_eq!(edge.import_kind, ImportKind::Named);
    }

    #[test]
    fn test_call_edge() {
        let edge = CallEdge {
            caller: CodePaths::symbol_node_id("src/lib.rs", "main"),
            callee: Some(CodePaths::symbol_node_id("src/lib.rs", "helper")),
            callee_name: "helper".to_string(),
            line: 42,
        };

        assert_eq!(edge.line, 42);
        assert!(edge.callee.is_some());
    }
}

