            cognitiveos_v3_core::encode_payload_gzip_json(&payload).expect("encode payload");

        cognitiveos_v3_core::EventNodeOwned {
            id: node_id,
            parent_id: None,
            path: Some(path),
            timestamp: 0,
            timestamp_vector: vec![],
            content_hash: None,
            content_uri: None,
            vector_uri: None,
            payload: payload_bytes,
            schema_type: Some("code/file".to_string()),
            entities_involved: vec![],
            community_members: vec![],
        }
    }

    /// Create a symbol node.
    pub fn create_symbol(
        &self,
        payload: SymbolPayload,
        parent_id: NodeId,
    ) -> cognitiveos_v3_core::EventNodeOwned {
        let path = CodePaths::symbol_path(
            &self.domain,
            None,
            &payload.file_path,
            &payload.qualified_name,
        );
        let node_id = CodePaths::symbol_node_id(&payload.file_path, &payload.qualified_name);
        let payload_bytes =
            cognitiveos_v3_core::encode_payload_gzip_json(&payload).expect("encode payload");

        cognitiveos_v3_core::EventNodeOwned {
            id: node_id,
            parent_id: Some(parent_id),
            path: Some(path),
            timestamp: 0,
            timestamp_vector: vec![],
            content_hash: None,
            content_uri: None,
            vector_uri: None,
            payload: payload_bytes,
            schema_type: Some("code/symbol".to_string()),
            entities_involved: vec![],
            community_members: vec![],
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_language_from_extension() {
        assert_eq!(Language::from_extension("rs"), Language::Rust);
        assert_eq!(Language::from_extension("py"), Language::Python);
        assert_eq!(Language::from_extension("ts"), Language::TypeScript);
        assert_eq!(
            Language::from_extension("unknown"),
            Language::Other("unknown".to_string())
        );
    }

    #[test]
    fn test_code_paths() {
        let path = CodePaths::file_path("code", Some("my-repo"), "src/main.rs");
        assert!(path.contains("my-repo"));
        assert!(path.contains("src/main.rs"));

        let sym_path = CodePaths::symbol_path("code", None, "lib.rs", "MyStruct");
        assert!(sym_path.contains("lib.rs"));
        assert!(sym_path.contains("MyStruct"));
    }

    #[test]
    fn test_symbol_payload() {
        let payload = SymbolPayload {
            name: "my_function".to_string(),
            qualified_name: "mymodule::my_function".to_string(),
            kind: SymbolKind::Function,
            language: Language::Rust,
            file_path: "src/lib.rs".to_string(),
            start_line: 10,
            end_line: 20,
            signature: Some("fn my_function(x: i32) -> bool".to_string()),
            docstring: Some("Does something useful.".to_string()),
            parameters: vec![ParameterInfo {
                name: "x".to_string(),
                type_annotation: Some("i32".to_string()),
                default_value: None,
            }],
            return_type: Some("bool".to_string()),
        };

        assert_eq!(payload.name, "my_function");
        assert_eq!(payload.kind, SymbolKind::Function);
    }

    #[test]
    fn test_code_file_payload() {
        let payload = CodeFilePayload {
            path: "src/main.rs".to_string(),
            language: Language::Rust,
            repo_id: Some("my-repo".to_string()),
            commit_sha: Some("abc123".to_string()),
            content_hash: "def456".to_string(),
            line_count: 100,
            imports: vec!["std::collections::HashMap".to_string()],
            exports: vec!["main".to_string()],
            symbols: vec!["main".to_string()],
        };

        assert_eq!(payload.language, Language::Rust);
        assert_eq!(payload.line_count, 100);
    }

    #[test]
    fn test_import_edge() {
        let edge = ImportEdge {
            from_file: CodePaths::file_node_id("src/lib.rs", "abc123def456"),
            import_name: "HashMap".to_string(),
            target_module: "std::collections".to_string(),
            import_kind: ImportKind::Named,
        };

        assert_eq!(edge.import_kind, ImportKind::Named);
    }

    #[test]
    fn test_call_edge() {
        let edge = CallEdge {
            caller: CodePaths::symbol_node_id("src/lib.rs", "main"),
            callee: Some(CodePaths::symbol_node_id("src/lib.rs", "helper")),
            callee_name: "helper".to_string(),
            line: 42,
        };

        assert_eq!(edge.line, 42);
        assert!(edge.callee.is_some());
    }
}

