=== GRAPH STORE TRAIT ===
use anyhow::Result;
use cognitiveos_v3_core::NodeKey;
use roaring::RoaringBitmap;

pub type CommunityId = String;
pub type EntityId = String;

/// Metadata for a community (for observability).
#[derive(Clone, Debug, Default, serde::Serialize, serde::Deserialize)]
pub struct CommunityMeta {
    /// Number of members.
    pub size: usize,
    /// Jaccard stability vs previous run (0.0-1.0).
    pub stability: Option<f32>,
    /// Last update timestamp (ms).
    pub updated_at: i64,
}

/// Metadata for the last offline community recompute run.
#[derive(Clone, Debug, Default, serde::Serialize, serde::Deserialize, PartialEq)]
pub struct CommunityRecomputeMeta {
    /// Community partition algorithm identifier (e.g. "leiden").
    pub community_algo: String,
    /// Algorithm implementation version (crate semver or build identifier).
    pub community_algo_version: String,
    /// Algorithm params used for this run.
    pub community_params: serde_json::Value,
    /// Recompute timestamp (ms since epoch).
    pub community_recomputed_at: i64,
}

pub trait GraphStore {
    fn add_child(&self, parent: NodeKey, child: NodeKey) -> Result<()>;
    fn add_edge(&self, a: NodeKey, b: NodeKey) -> Result<()>;
    fn remove_edge(&self, a: NodeKey, b: NodeKey) -> Result<()>;
    fn remove_node(&self, node: NodeKey) -> Result<()>;
    fn remove_child(&self, parent: NodeKey, child: NodeKey) -> Result<()>;

    fn get_children(&self, parent: NodeKey) -> Result<Vec<NodeKey>>;
    fn get_parent(&self, child: NodeKey) -> Result<Option<NodeKey>>;
    fn get_neighbors(&self, node: NodeKey) -> Result<Vec<NodeKey>>;

    /// Get all descendants of a node (children, grandchildren, etc.) in bottom-up order.
    /// Bottom-up order ensures children are deleted before parents during cascade delete.
    fn get_descendants(&self, root: NodeKey) -> Result<Vec<NodeKey>>;

    // === Community API ===

    fn set_community_members(&self, comm: &CommunityId, members: &RoaringBitmap) -> Result<()>;
    fn add_to_community(&self, comm: &CommunityId, node: NodeKey) -> Result<()>;
    fn remove_from_community(&self, comm: &CommunityId, node: NodeKey) -> Result<()>;
    fn get_community(&self, comm: &CommunityId) -> Result<Option<RoaringBitmap>>;

    /// Get all communities a node belongs to.
    /// Returns communities in deterministic order (sorted by ID).
    fn node_communities(&self, node: NodeKey) -> Result<Vec<CommunityId>>;

    /// Iterate all communities with their members.
    /// Returns communities in deterministic order (sorted by ID).
    fn iter_communities(&self) -> Result<Vec<(CommunityId, RoaringBitmap)>>;
