use anyhow::{Result, bail};
use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, PartialEq)]
pub struct MultiVector64 {
    pub scalar: f32,
    pub vector: [f32; 64],
}

pub fn from_projected_embedding(vector: [f32; 64]) -> MultiVector64 {
    MultiVector64 {
        scalar: 0.0,
        vector,
    }
}

pub fn inner_product(a: &MultiVector64, b: &MultiVector64) -> f32 {
    a.scalar * b.scalar
        + a.vector
            .iter()
            .zip(b.vector.iter())
            .map(|(l, r)| l * r)
            .sum::<f32>()
}

pub fn wedge_magnitude_64(a: &MultiVector64, b: &MultiVector64) -> f32 {
    let a_norm_sq = inner_product(a, a);
    let b_norm_sq = inner_product(b, b);
    let inner = inner_product(a, b);
    (a_norm_sq * b_norm_sq - inner * inner).max(0.0).sqrt()

